package com.steven.assets.bff.publicsrpp;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.http.MediaType;
import static org.assertj.core.api.Assertions.*;
class SrppUsReportResponseValidatorTest {
 private static final ObjectMapper M=new ObjectMapper();
 static ObjectNode fixture() throws Exception {try(var in=SrppUsReportResponseValidatorTest.class.getResourceAsStream("/srpp/us-report-package.json")){ObjectNode root=(ObjectNode)M.readTree(in);coherentLegacyFixture(root);return root;}}
 private static void coherentLegacyFixture(ObjectNode root){ObjectNode sources=(ObjectNode)root.path("inputBundle").path("sources"),policy=(ObjectNode)sources.path("policy"),model=M.createObjectNode().put("decision","D-201");String rawModel=model.toString();ObjectNode manifest=M.createObjectNode().put("schema_version",1).put("decision","D-201").put("policy_version","SYNTHETIC_LEGACY").put("model_version","SYNTHETIC_LEGACY");manifest.putObject("files").put("assumptions/model_inputs.json",SrppJcs.sha256Hex(rawModel));String hash=SrppJcs.sha256Hex(SrppJcs.canonicalize(manifest));manifest.put("POLICY_BUNDLE_SHA256",hash);String rawManifest=manifest.toString();policy.put("rawModelBytes",rawModel).put("rawManifestBytes",rawManifest).put("bundleHash",hash).put("modelInputsSha256",SrppJcs.sha256Hex(rawModel)).put("policyManifestSha256",SrppJcs.sha256Hex(rawManifest));((ObjectNode)root.path("identity")).put("policyBundleSha256",hash);((ObjectNode)root.path("sourceVector").path("policy")).put("sha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(policy)));root.put("inputSnapshotSha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(root.path("inputBundle"))));seal(root);}
 private static SrppUsReportQuery q()throws Exception{return new SrppUsReportQuery(null,"Codex","US","2026-11-03","US_OPEN_0945",fixture().path("identity").path("policyBundleSha256").asText(),"b".repeat(64),null);}
 private static byte[] bytes(ObjectNode n) throws Exception{return M.writeValueAsBytes(n);}
 private static void seal(ObjectNode n){n.remove("contentSha256");n.put("contentSha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(n)));}
 @Test void acceptsFrozenUnavailableScopeWithoutMakingItComplete() throws Exception{SrppUsReportResponseValidator.validate(q(),7L,MediaType.APPLICATION_JSON,bytes(fixture()));}
 @Test void rejectsCrossOwnerConsumerMarketSessionPolicySwaggerAndRun() throws Exception{for(String key:java.util.List.of("consumer","market","sessionDate","reportSlot","policyBundleSha256","swaggerSha256")){var n=fixture();((ObjectNode)n.get("identity")).put(key,"wrong");seal(n);assertThatThrownBy(()->SrppUsReportResponseValidator.validate(q(),7L,MediaType.APPLICATION_JSON,bytes(n))).isInstanceOf(RuntimeException.class);}assertThatThrownBy(()->SrppUsReportResponseValidator.validate(q(),8L,MediaType.APPLICATION_JSON,bytes(fixture()))).isInstanceOf(RuntimeException.class);}
 @Test void rejectsContentAndSourceHashMutationAndFlagOnlyCompletion() throws Exception{var n=fixture();n.put("contentSha256","0".repeat(64));assertThatThrownBy(()->SrppUsReportResponseValidator.validate(q(),7L,MediaType.APPLICATION_JSON,bytes(n))).isInstanceOf(RuntimeException.class);var changed=fixture();((ObjectNode)changed.get("sourceVector").get("assets")).put("sha256","0".repeat(64));seal(changed);assertThatThrownBy(()->SrppUsReportResponseValidator.validate(q(),7L,MediaType.APPLICATION_JSON,bytes(changed))).isInstanceOf(RuntimeException.class);var flag=fixture();((ObjectNode)flag.get("modules").get(0)).put("coverage","COMPLETE");seal(flag);assertThatThrownBy(()->SrppUsReportResponseValidator.validate(q(),7L,MediaType.APPLICATION_JSON,bytes(flag))).isInstanceOf(RuntimeException.class);}
 @Test void rejectsUnknownFieldsAndWrongContentType() throws Exception{var n=fixture();n.put("extra",true);seal(n);assertThatThrownBy(()->SrppUsReportResponseValidator.validate(q(),7L,MediaType.APPLICATION_JSON,bytes(n))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->SrppUsReportResponseValidator.validate(q(),7L,MediaType.TEXT_HTML,bytes(fixture()))).isInstanceOf(RuntimeException.class);}
 @Test void generatedPublisherEnvelopeCrossesTheIndependentBffBoundary() throws Exception{
  String path=System.getProperty("us.fixture");org.junit.jupiter.api.Assumptions.assumeTrue(path!=null,"publisher integration fixture supplied by isolated PG test");
  byte[] raw=java.nio.file.Files.readAllBytes(java.nio.file.Path.of(path));var r=M.readTree(raw);var i=r.get("identity");var query=new SrppUsReportQuery(null,i.path("consumer").asText(),"US",i.path("sessionDate").asText(),"US_OPEN_0945",i.path("policyBundleSha256").asText(),i.path("swaggerSha256").asText(),r.path("calculationRunId").asText());
  SrppUsReportResponseValidator.validate(query,i.path("ownerUserId").asLong(),MediaType.APPLICATION_JSON,raw);
 }

 @Test void currentD236CannotDowngradeToLegacyTwoModulesEvenWithResealedEnvelope()throws Exception{
  ObjectNode root=fixture(),model=SrppZeroTargetExitValidatorTest.fixture().model();String modelBytes=SrppJcs.canonicalize(model);ObjectNode manifest=M.createObjectNode().put("decision","D-236");manifest.putObject("files").put("assumptions/model_inputs.json",SrppJcs.sha256Hex(modelBytes));String hash=SrppJcs.sha256Hex(SrppJcs.canonicalize(manifest));manifest.put("POLICY_BUNDLE_SHA256",hash);
  ObjectNode sources=(ObjectNode)root.path("inputBundle").path("sources"),policy=(ObjectNode)sources.path("policy");policy.put("bundleHash",hash).put("rawModelBytes",modelBytes).put("rawManifestBytes",SrppJcs.canonicalize(manifest));((ObjectNode)root.path("identity")).put("policyBundleSha256",hash);
  ((ObjectNode)root.path("sourceVector").path("policy")).put("sha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(policy)));root.put("inputSnapshotSha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(root.path("inputBundle"))));seal(root);
  SrppUsReportQuery query=new SrppUsReportQuery(null,"Codex","US","2026-11-03","US_OPEN_0945",hash,"b".repeat(64),null);
  policy.put("modelInputsSha256",SrppJcs.sha256Hex(modelBytes)).put("policyManifestSha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(manifest)));((ObjectNode)root.path("sourceVector").path("policy")).put("sha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(policy)));root.put("inputSnapshotSha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(root.path("inputBundle"))));seal(root);
  assertThat(SrppZeroTargetExitValidator.current(policy)).isTrue();assertThatThrownBy(()->SrppUsReportResponseValidator.validate(query,7L,MediaType.APPLICATION_JSON,bytes(root))).isInstanceOf(RuntimeException.class);
  for(boolean remove:java.util.List.of(false,true)){ObjectNode changed=model.deepCopy();if(remove)((ObjectNode)changed.path("execution_policy")).remove("zero_target_high_zone_exit_d236");else ((ObjectNode)changed.at("/execution_policy/zero_target_high_zone_exit_d236")).put("enabled",false);policy.put("rawModelBytes",SrppJcs.canonicalize(changed));((ObjectNode)root.path("sourceVector").path("policy")).put("sha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(policy)));root.put("inputSnapshotSha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(root.path("inputBundle"))));seal(root);assertThatThrownBy(()->SrppUsReportResponseValidator.validate(query,7L,MediaType.APPLICATION_JSON,bytes(root))).isInstanceOf(RuntimeException.class);}
 }

 @Test @org.junit.jupiter.api.condition.EnabledIfSystemProperty(named="srpp.d236.publisher.dir",matches=".+")
 void actualD236UsPublisherCompletePositiveAndBlockedWiresValidate()throws Exception{for(String name:java.util.List.of("actionable","blocked")){byte[] raw=java.nio.file.Files.readAllBytes(java.nio.file.Path.of(System.getProperty("srpp.d236.publisher.dir"),"us-"+name+".json"));JsonNode root=SrppDailyContextResponseValidator.parseStrict(raw),identity=root.path("identity");var query=new SrppUsReportQuery(null,identity.path("consumer").asText(),"US",identity.path("sessionDate").asText(),identity.path("reportSlot").asText(),identity.path("policyBundleSha256").asText(),identity.path("swaggerSha256").asText(),root.path("calculationRunId").asText());SrppUsReportResponseValidator.validate(query,identity.path("ownerUserId").asLong(),MediaType.APPLICATION_JSON,raw);assertThat(root.path("modules").size()).isEqualTo(3);JsonNode found=null;for(JsonNode module:root.path("modules"))for(JsonNode leg:module.path("data").path("legs"))if(SrppZeroTargetExitValidator.STRATEGY.equals(leg.path("strategy").asText())){assertThat(found).isNull();found=leg;}assertThat(found).isNotNull();assertThat(found.path("status").asText()).isEqualTo(name.equals("actionable")?"ACTIONABLE_FOR_REPORT":"BLOCKED");assertThat(found.path("units").asText()).isEqualTo(name.equals("actionable")?"300":"0");}}

 @Test @org.junit.jupiter.api.condition.EnabledIfSystemProperty(named="srpp.d236.publisher.dir",matches=".+")
 void dualDecisionDowngradeCannotKeepTheExpectedCurrentHash()throws Exception{for(String mode:java.util.List.of("retainedSeal","recomputedSeal","removedSeal")){ObjectNode root=(ObjectNode)SrppDailyContextResponseValidator.parseStrict(java.nio.file.Files.readAllBytes(java.nio.file.Path.of(System.getProperty("srpp.d236.publisher.dir"),"us-blocked.json")));var i=root.path("identity");var expected=new SrppUsReportQuery(null,i.path("consumer").asText(),"US",i.path("sessionDate").asText(),i.path("reportSlot").asText(),i.path("policyBundleSha256").asText(),i.path("swaggerSha256").asText(),root.path("calculationRunId").asText());ObjectNode policy=(ObjectNode)root.at("/inputBundle/sources/policy"),model=(ObjectNode)SrppZeroTargetExitValidator.parse(policy.path("rawModelBytes")),manifest=(ObjectNode)SrppZeroTargetExitValidator.parse(policy.path("rawManifestBytes"));model.put("decision","D-235");((ObjectNode)model.path("execution_policy")).remove("zero_target_high_zone_exit_d236");manifest.put("decision","D-235");String rawModel=model.toString();manifest.withObject("files").put("assumptions/model_inputs.json",SrppJcs.sha256Hex(rawModel));if(mode.equals("recomputedSeal")){manifest.remove("POLICY_BUNDLE_SHA256");manifest.put("POLICY_BUNDLE_SHA256",SrppJcs.sha256Hex(SrppJcs.canonicalize(manifest)));}else if(mode.equals("removedSeal"))manifest.remove("POLICY_BUNDLE_SHA256");String rawManifest=manifest.toString();policy.put("rawModelBytes",rawModel).put("rawManifestBytes",rawManifest).put("modelInputsSha256",SrppJcs.sha256Hex(rawModel)).put("policyManifestSha256",SrppJcs.sha256Hex(rawManifest));com.fasterxml.jackson.databind.node.ArrayNode modules=(com.fasterxml.jackson.databind.node.ArrayNode)root.path("modules");for(int n=modules.size()-1;n>=0;n--)if(modules.get(n).path("moduleId").asText().equals("ZERO_TARGET_EXIT"))modules.remove(n);((ObjectNode)root.at("/sourceVector/policy")).put("sha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(policy)));root.put("inputSnapshotSha256",SrppJcs.sha256Hex(SrppJcs.canonicalize(root.path("inputBundle"))));seal(root);assertThat(root.path("identity").path("policyBundleSha256").asText()).isEqualTo(expected.policyBundleSha256());assertThatThrownBy(()->SrppUsReportResponseValidator.validate(expected,i.path("ownerUserId").asLong(),MediaType.APPLICATION_JSON,bytes(root))).as(mode).isInstanceOf(RuntimeException.class);}}
 @Test @org.junit.jupiter.api.condition.EnabledIfSystemProperty(named="srpp.d236.publisher.dir",matches=".+")
 void actualUsPartialMarketCompositeCanKeepCompleteNativeLeg()throws Exception{ObjectNode root=(ObjectNode)SrppDailyContextResponseValidator.parseStrict(java.nio.file.Files.readAllBytes(java.nio.file.Path.of(System.getProperty("srpp.d236.publisher.dir"),"us-actionable.json")));var i=root.path("identity");var q=new SrppUsReportQuery(null,i.path("consumer").asText(),"US",i.path("sessionDate").asText(),i.path("reportSlot").asText(),i.path("policyBundleSha256").asText(),i.path("swaggerSha256").asText(),root.path("calculationRunId").asText());((ObjectNode)root.at("/sourceVector/market")).put("coverage","PARTIAL");seal(root);SrppUsReportResponseValidator.validate(q,i.path("ownerUserId").asLong(),MediaType.APPLICATION_JSON,bytes(root));}
}
